// Freiraum – Praxisinhalte: Übungen, Begriffe, Monatsthemen, Bestandsaufnahme
// Autor und Auftraggeber: Carlo Maximilian Engeländer. Alle Rechte vorbehalten.

const UEBUNGEN=[
// ---------- Kleidung ----------
{ id:"u01", cat:"kl", t:"Die halbe Kleiderstange", d:7,
  x:"Schiebe die Hälfte deiner Kleidung an ein Ende der Stange oder in eine Kiste. Eine Woche lang ziehst du dich nur aus der anderen Hälfte an. Am Ende schaust du, was dir gefehlt hat und was nicht.",
  steps:["Teile deine Kleidung nach Gefühl in zwei Hälften.","Leg die eine Hälfte sichtbar, aber getrennt zur Seite.","Trag sieben Tage lang nur Teile aus der anderen Hälfte.","Notiere jedes Teil, das du aus der getrennten Hälfte holen wolltest.","Entscheide am Ende in Ruhe, ob du etwas in die Vielleicht-Kiste legst."],
  wenn:"Wenn ich morgens vor dem Schrank stehe und mir nichts gefällt, dann nehme ich das oberste passende Teil aus meiner Hälfte und schreibe den Wunsch kurz auf.",
  warum:"Ob weniger Auswahl am Morgen wirklich Kraft spart, ist in der Forschung umstritten, deshalb prüfst du es an dir selbst.",
  imp:"i42" },

{ id:"u02", cat:"kl", t:"Bügel umdrehen", d:30,
  x:"Häng alle Kleiderbügel verkehrt herum in den Schrank. Sobald du ein Teil getragen und zurückgehängt hast, drehst du seinen Bügel richtig herum. Nach 30 Tagen siehst du auf einen Blick, was du gar nicht angezogen hast.",
  steps:["Dreh heute alle Bügel so, dass der Haken zu dir zeigt.","Häng getragene Teile mit richtig gedrehtem Bügel zurück.","Mach für Gefaltetes eine kleine Strichliste an der Schranktür.","Schau dir nach 30 Tagen die verkehrt hängenden Teile an.","Frag dich bei jedem, ob es nur zur Jahreszeit nicht passt oder ob du es nicht mehr magst."],
  wenn:"Wenn nach 30 Tagen ein Teil verkehrt hängt und gerade Saison hat, dann lege ich es in die Vielleicht-Kiste statt in den Müll.",
  warum:"Viele Menschen besitzen Kleidung, die sie kaum oder nie tragen, und dieser Test zeigt dir, ob das bei dir auch so ist.",
  imp:"i26" },

{ id:"u03", cat:"kl", t:"Ein Teil wieder tragbar machen", d:5,
  x:"Such ein Kleidungsstück heraus, das du nur wegen eines kleinen Schadens nicht trägst. Ein loser Knopf, eine offene Naht oder ein Loch reicht. Lerne in den nächsten Tagen, es selbst zu flicken, oder bring es zu einer Schneiderei.",
  steps:["Such ein Teil mit einem kleinen Schaden heraus.","Schau dir eine Anleitung an oder frag jemanden, der nähen kann.","Besorg Nadel und passendes Garn oder leih dir beides.","Flick das Teil oder gib es zur Reparatur.","Trag es in der Woche danach mindestens einmal."],
  wenn:"Wenn ich beim Anziehen einen losen Knopf bemerke, dann lege ich das Teil sofort in eine kleine Flickschale und nicht zurück in den Schrank.",
  warum:"Nach der Selbstbestimmungstheorie tut es gut, sich fähig und selbstständig zu fühlen, und etwas selbst zu reparieren, kann dieses Gefühl stärken.",
  imp:"i17",
  s:"Such ein eigenes Kleidungsstück heraus, das du nur wegen eines kleinen Schadens nicht trägst. Frag zu Hause, ob dir jemand zeigt, wie man einen Knopf annäht oder eine Naht schließt. Nadel und Garn gibt es oft schon im Haushalt." },

{ id:"u04", cat:"kl", t:"Kleidertausch mit Freunden", d:14,
  x:"Verabrede dich in den nächsten zwei Wochen mit ein paar Menschen zu einem kleinen Kleidertausch. Jeder bringt gut erhaltene Teile mit, die er nicht mehr trägt. Was am Ende übrig bleibt, geht gemeinsam zu einer Kleiderkammer.",
  steps:["Frag drei bis fünf Menschen, ob sie mitmachen.","Leg einen Termin und einen Ort fest.","Such pro Person höchstens zehn saubere, heile Teile heraus.","Nimm beim Tausch nur Teile mit, die du dir sofort anziehen würdest.","Bring die übrigen Teile gemeinsam zu einer Kleiderkammer."],
  wenn:"Wenn ich beim Tausch ein Teil nur nehme, weil es umsonst ist, dann lege ich es zurück auf den Tisch.",
  warum:"Kleidung wird heute im Schnitt kürzer getragen als früher, und ein Tausch verlängert ihre Nutzung, ohne dass etwas Neues hergestellt wird.",
  imp:"i27",
  s:"Verabrede dich mit Freundinnen oder Freunden zu einem kleinen Kleidertausch. Bring nur eigene Kleidung mit und frag vorher deine Eltern, ob du sie weitergeben darfst. Was übrig bleibt, geht gemeinsam zu einer Kleiderkammer." },

{ id:"u05", cat:"kl", t:"Drei Wochen nichts Neues zum Anziehen", d:21,
  x:"Kauf drei Wochen lang keine neue Kleidung, auch keine Schnäppchen. Wenn wirklich etwas fehlt, leihst du es, kaufst es gebraucht oder parkst den Wunsch. Socken und Unterwäsche, die kaputt sind, darfst du ersetzen.",
  steps:["Schreib dir das Startdatum in den Kalender.","Park jeden Kleidungswunsch in der App, statt ihn sofort zu kaufen.","Kombinier ein Teil, das du lange nicht getragen hast, neu.","Schau nach drei Wochen, welche Wünsche noch da sind."],
  wenn:"Wenn ich online auf ein Kleidungsangebot klicke, dann lege ich es nicht in den Warenkorb, sondern parke es als Wunsch.",
  warum:"Nach einer britischen Modellrechnung wiegt die Herstellung von Kleidung schwer, darum bringt längeres Tragen am meisten, wenn dadurch ein Neukauf wegfällt.",
  imp:"i28",
  s:"Kauf dir drei Wochen lang keine neue Kleidung von deinem Geld und bitte auch niemanden darum. Wenn etwas wirklich fehlt, zum Beispiel weil Schuhe zu klein sind, sprich mit deinen Eltern. Andere Kleidungswünsche parkst du in der App." },

// ---------- Wohnen ----------
{ id:"u06", cat:"wo", t:"Eine Schublade am Tag", d:7,
  x:"Nimm dir eine Woche lang jeden Tag genau eine Schublade oder ein Fach vor. Du räumst alles aus, wischst kurz durch und legst nur zurück, was hineingehört und was du benutzt. Der Rest bekommt einen anderen Platz oder geht weiter.",
  steps:["Such dir sieben Schubladen oder Fächer aus.","Räum jeden Tag eine davon ganz aus.","Leg zurück, was du benutzt und was dorthin gehört.","Gib Doppeltes und Brauchbares in eine Weitergeben-Tüte.","Hör nach einer Schublade auf, auch wenn du Lust auf mehr hast."],
  wenn:"Wenn ich abends den Wasserkocher anschalte, dann räume ich in der Wartezeit die Schublade des Tages aus.",
  warum:"In einer kleinen Studie hatten Frauen, die ihr Zuhause als unordentlich beschrieben, einen ungünstigeren Tagesverlauf des Stresshormons Cortisol, und ob Aufräumen dir Ruhe bringt, kannst du nur an dir beobachten.",
  imp:"i08",
  s:"Nimm dir eine Woche lang jeden Tag eine eigene Schublade oder ein Fach in deinem Zimmer vor. Räum es aus und leg nur zurück, was du benutzt. Gemeinsame Schubladen der Familie räumst du nur nach Absprache auf." },

{ id:"u07", cat:"wo", t:"Reparieren vor Ersetzen", d:14,
  x:"Such ein kaputtes Ding im Haushalt heraus und finde in zwei Wochen heraus, ob man es reparieren kann. Ein Reparatur-Café, eine Anleitung oder ein Fachbetrieb können helfen. Geräte mit Netzstrom oder Lithium-Akku nur stromlos öffnen. Akkus und Netzteile reparieren Fachleute.",
  steps:["Wähl ein kaputtes Ding aus, das du eigentlich ersetzen wolltest.","Schreib genau auf, was nicht mehr geht.","Such nach einem Reparatur-Café in deiner Nähe oder nach einer Anleitung.","Probier die Reparatur oder lass sie machen.","Gib das Ding zum Recyclinghof, wenn es wirklich nicht zu retten ist."],
  wenn:"Wenn ich den Gedanken habe, etwas Kaputtes neu zu kaufen, dann suche ich zuerst zehn Minuten nach einer Reparaturmöglichkeit.",
  warum:"Bei Handys und Notebooks steckt ein großer Teil der Klimalast schon in der Herstellung, darum zählt dort jedes Jahr, das ein Gerät länger hält.",
  imp:"i29",
  s:"Such ein eigenes Ding heraus, das kaputt ist, zum Beispiel Kopfhörer, eine Lampe oder ein Fahrradteil. Finde heraus, ob man es reparieren kann. Bei Geräten mit Netzstecker oder Akku arbeitest du nur mit einer erwachsenen Person zusammen." },

{ id:"u08", cat:"wo", t:"Das teure Ding im Schrank", d:3,
  x:"Such ein Ding, das du kaum benutzt und nur behältst, weil es viel Geld gekostet hat. Frag dich drei Tage lang: Würde ich es heute für diesen Preis kaufen? Danach entscheidest du, ob du es benutzt, verkaufst, verleihst oder in die Vielleicht-Kiste legst.",
  steps:["Such ein teures Ding, das du selten benutzt.","Stell es drei Tage lang an einen Platz, an dem du es siehst.","Frag dich jeden Tag, ob du es heute noch einmal kaufen würdest.","Entscheide am dritten Tag, was damit passiert."],
  wenn:"Wenn ich denke „Es war doch so teuer“, dann frage ich mich, ob ich es heute noch einmal kaufen würde.",
  warum:"Geld, das schon ausgegeben ist, kommt nicht zurück, und trotzdem halten Menschen oft an Dingen fest, weil sie einmal viel gekostet haben.",
  imp:"i06",
  s:"Such ein eigenes Ding, das du kaum benutzt und nur behältst, weil es teuer war. Frag dich drei Tage lang, ob du es heute noch einmal haben wollen würdest. Wenn deine Eltern es bezahlt haben, besprich mit ihnen, was damit passiert." },

{ id:"u09", cat:"wo", t:"Was macht dich fähig?", d:7,
  x:"Geh eine Woche lang dein Werkzeug, deine Küchengeräte oder deine Hobbysachen durch. Probier jedes Teil kurz aus. Was dich fähig macht, behältst du mit Grund. Doppeltes und Ungenutztes verleihst oder verschenkst du an Menschen, die es brauchen.",
  steps:["Wähl einen Bereich aus, zum Beispiel Werkzeugkiste, Küche oder Bastelkiste.","Prüf an jedem Tag einen Teil davon.","Markier Dinge, die dich etwas selbst tun lassen.","Leg Doppeltes zur Seite und frag in deinem Umfeld, wer es braucht.","Trag das wichtigste Teil in der App als „macht mich fähig“ ein."],
  wenn:"Wenn ich zwei Dinge für denselben Zweck finde, dann behalte ich das bessere und frage, wer das andere brauchen kann.",
  warum:"Nach der Selbstbestimmungstheorie tut es gut, sich fähig und selbstständig zu fühlen, und Dinge, mit denen du etwas selbst kannst, tragen vielleicht dazu bei.",
  imp:"i17",
  s:"Geh eine Woche lang deine eigenen Hobbysachen, Bastelsachen oder Sportsachen durch. Probier jedes Teil kurz aus. Was dich etwas selbst tun lässt, behältst du mit Grund. Werkzeug der Familie bleibt, wo es ist." },

{ id:"u10", cat:"wo", t:"Eine freie Fläche", d:21,
  x:"Wähl eine Fläche aus, zum Beispiel den Esstisch, den Schreibtisch oder die Kommode im Flur. Drei Wochen lang räumst du sie jeden Abend leer. Achte darauf, wie es sich anfühlt, morgens auf eine freie Fläche zu schauen.",
  steps:["Such dir eine Fläche aus, auf der sich oft Dinge sammeln.","Räum sie heute ganz leer.","Gib jedem Ding, das dort lag, einen festen Platz.","Räum die Fläche jeden Abend in zwei Minuten frei.","Notiere einmal pro Woche, was sich dort immer wieder sammelt."],
  wenn:"Wenn ich abends das Licht im Zimmer ausschalte, dann räume ich vorher die Fläche frei.",
  warum:"In einer Laborstudie mit einfachen Formen konkurrierten mehrere Dinge im Blickfeld um die Verarbeitung im Gehirn, und ob dir eine freie Fläche hilft, probierst du hier aus.",
  imp:"i11",
  s:"Wähl eine eigene Fläche aus, zum Beispiel deinen Schreibtisch oder dein Nachttischchen. Drei Wochen lang räumst du sie jeden Abend frei. Achte darauf, wie es sich anfühlt, dort morgens oder bei den Hausaufgaben auf eine freie Fläche zu schauen." },

// ---------- Papier & Digitales ----------
{ id:"u11", cat:"pa", t:"Der Papierstapel auf null", d:7,
  x:"Sammle alle losen Papiere an einem Ort, also Briefe, Rechnungen, Zettel und Prospekte. Eine Woche lang bearbeitest du jeden Tag einen Teil. Am Ende liegt nichts mehr herum, und alles Wichtige steckt in einem Ordner.",
  steps:["Sammle heute alle losen Papiere in einer Kiste.","Leg einen einzigen Ordner für Wichtiges bereit.","Bearbeite jeden Tag eine Handvoll Papiere.","Erledige, was weniger als zwei Minuten dauert, sofort.","Bring Altpapier gleich zum Container."],
  wenn:"Wenn ich Post aus dem Briefkasten hole, dann öffne ich sie noch im Flur und lege sie in den Ordner oder ins Altpapier.",
  warum:"Eine Laborstudie deutet an, dass Ungeordnetes im Blickfeld um Aufmerksamkeit konkurriert, und ob dir ein Stapel auf null Ruhe bringt, merkst du nach dieser Woche.",
  imp:"i11",
  s:"Sammle alle deine losen Papiere an einem Ort, also Arbeitsblätter, Zettel aus der Schule und alte Notizen. Bearbeite eine Woche lang jeden Tag einen Teil. Am Ende steckt alles, was du noch brauchst, in einer Mappe. Elternbriefe gibst du sofort ab." },

{ id:"u12", cat:"pa", t:"Werbung abbestellen", d:3,
  x:"Bestell drei Tage lang jede Werbung ab, die bei dir ankommt. Das gilt für Newsletter im Postfach, Benachrichtigungen von Shop-Apps und Prospekte im Briefkasten. Ein Aufkleber gegen Werbung am Briefkasten hilft dabei.",
  steps:["Such im Postfach nach dem Wort „abbestellen“ und klick dich durch.","Schalte bei Shop-Apps die Benachrichtigungen aus.","Lösch Shop-Apps, die du nur aus Langeweile öffnest.","Kleb einen Hinweis gegen Werbung an deinen Briefkasten."],
  wenn:"Wenn eine Werbe-Mail ankommt, dann bestelle ich sie ab, bevor ich sie lese.",
  warum:"Bei Kindern ging mehr Fernsehwerbung mit stärkeren Produktwünschen und mehr Materialismus einher, und weniger Werbung nimmt Anlässe für neue Wünsche weg.",
  imp:"i36",
  s:"Bestell drei Tage lang jede Werbung ab, die auf deinem Handy und in deinem Postfach ankommt. Schalte bei Shop-Apps die Benachrichtigungen aus. Den Briefkasten der Familie fasst du nur an, wenn deine Eltern einverstanden sind." },

{ id:"u13", cat:"pa", t:"Ein Monat Fotos am Abend", d:14,
  x:"Geh zwei Wochen lang jeden Abend die Fotos eines Monats auf deinem Handy durch. Lösch Doppelte, unscharfe Bilder und Bildschirmfotos, die du nicht mehr brauchst. Markier pro Monat deine liebsten Bilder als Favoriten.",
  steps:["Sichere zuerst alle Fotos an einem zweiten Ort, etwa auf einem Computer oder einer Festplatte.","Fang mit dem ältesten Monat auf deinem Handy an.","Lösch Serien bis auf das beste Bild.","Lösch Bildschirmfotos, die erledigt sind.","Markier pro Monat höchstens zehn Lieblingsbilder."],
  wenn:"Wenn ich nach dem Abendessen den Tisch abgeräumt habe, dann sortiere ich einen Monat Fotos.",
  warum:"An schöne Zeiten zu denken, kann nach der Nostalgieforschung guttun, und das gelingt leichter, wenn die guten Bilder nicht zwischen Tausenden anderen verschwinden.",
  imp:"i33",
  s:"Geh zwei Wochen lang jeden Abend die Fotos eines Monats auf deinem Handy durch. Fotos liegen oft in einem Familienkonto oder werden mit anderen geteilt. Frag deshalb vorher, ob gelöschte Bilder auch bei anderen verschwinden, und sichere sie zuerst an einem zweiten Ort." },

{ id:"u14", cat:"pa", t:"Erst schauen, dann ein Foto", d:2,
  x:"Mach an zwei Tagen, an denen du etwas Besonderes erlebst, ein kleines Experiment. Du schaust zuerst eine Minute lang genau hin, bevor du das Handy herausholst. Danach machst du höchstens ein Foto pro Ort.",
  steps:["Such dir zwei Tage mit einem Ausflug oder einem Treffen aus.","Schau an jedem Ort zuerst eine Minute lang hin.","Mach danach höchstens ein Foto.","Schreib abends drei Dinge auf, an die du dich gut erinnerst."],
  wenn:"Wenn ich das Handy für ein Foto heraushole, dann stecke ich es noch einmal weg und schaue zuerst eine Minute hin.",
  warum:"In einer Studie erinnerten sich Menschen an Kunstwerke, die sie fotografiert hatten, schlechter als an solche, die sie nur angeschaut hatten.",
  imp:"i34" },

{ id:"u15", cat:"pa", t:"Das Handy im anderen Raum", d:7,
  x:"Leg dein Handy eine Woche lang jeden Tag für eine Stunde in einen anderen Raum. Nutze die Zeit zum Lernen, Lesen oder Arbeiten. Achte darauf, ob du dich anders konzentrieren kannst als sonst.",
  steps:["Wähl eine feste Stunde am Tag aus.","Stell das Handy auf lautlos und leg es in einen anderen Raum.","Mach in dieser Stunde eine Aufgabe, die Ruhe braucht.","Notiere danach in einem Satz, wie es dir ging."],
  wenn:"Wenn ich mich an den Schreibtisch setze, um etwas Wichtiges zu tun, dann bringe ich vorher das Handy in die Küche.",
  warum:"Ob schon die Nähe des Handys das Denken bremst, ist nach gescheiterten Wiederholungen unsicher, deshalb prüfst du es hier an dir selbst.",
  imp:"i35" },

// ---------- Erinnerungen ----------
{ id:"u16", cat:"er", t:"Foto und Geschichte", d:7,
  x:"Nimm eine Woche lang jeden Tag ein Erinnerungsstück in die Hand, das du nicht benutzt. Fotografiere es und schreib zwei, drei Sätze zu seiner Geschichte auf. Danach entscheidest du, ob es bleibt, weitergeht oder in die Vielleicht-Kiste kommt.",
  steps:["Stell eine Kiste mit Erinnerungsstücken bereit.","Fotografiere jeden Tag ein Stück bei gutem Licht.","Schreib auf, woher es kommt und woran es dich erinnert.","Entscheide ohne Eile, ob es bleibt oder weitergeht.","Frag bei Familienstücken, ob jemand anderes es haben möchte."],
  wenn:"Wenn ich ein Erinnerungsstück nicht weggeben mag, weil die Erinnerung daran hängt, dann fotografiere ich es und schreibe die Geschichte auf, bevor ich entscheide.",
  warum:"In Studien fiel es Menschen etwas leichter, ein Erinnerungsstück wegzugeben, wenn sie es vorher fotografiert hatten, weil sie dann weniger das Gefühl hatten, ein Stück von sich zu verlieren.",
  imp:"i07",
  s:"Nimm eine Woche lang jeden Tag ein eigenes Erinnerungsstück in die Hand, zum Beispiel ein altes Spielzeug oder eine Urkunde. Fotografiere es und schreib seine Geschichte auf. Bevor du etwas weggibst, frag deine Eltern, ob sie es behalten möchten." },

{ id:"u17", cat:"er", t:"Ein Erlebnis schenken", d:14,
  x:"Plan in den nächsten zwei Wochen das nächste Geschenk für einen Menschen als gemeinsames Erlebnis. Das kann ein Ausflug, ein gemeinsames Kochen oder ein Konzert sein. Schreib es auf eine Karte und verabrede einen festen Termin.",
  steps:["Denk an einen Menschen, der bald Geburtstag hat oder dem du etwas schenken willst.","Überleg, was ihr beide gern zusammen macht.","Schreib das Erlebnis auf eine selbst gestaltete Karte.","Mach beim Überreichen gleich einen Termin aus."],
  wenn:"Wenn ich im Laden ein Geschenk für jemanden suche, dann überlege ich zuerst, was wir zusammen erleben könnten.",
  warum:"In Studien fühlten sich Beschenkte nach einem Erlebnisgeschenk der schenkenden Person stärker verbunden als nach einem Sachgeschenk.",
  imp:"i40",
  s:"Plan das nächste Geschenk für einen Menschen als gemeinsames Erlebnis, das wenig oder nichts kostet. Das kann ein Spaziergang zu einem besonderen Ort, ein Spieleabend oder ein selbst gekochtes Essen sein. Schreib es auf eine Karte und mach einen Termin aus." },

{ id:"u18", cat:"er", t:"Ein Ehrenplatz", d:1,
  x:"Such heute ein Erinnerungsstück heraus, das dir wirklich etwas bedeutet und bisher in einer Kiste lag. Gib ihm einen Platz, an dem du es täglich siehst. Trag es in der App als „trägt Bedeutung“ ein.",
  steps:["Öffne eine Kiste oder Schublade mit Erinnerungsstücken.","Such das eine Stück aus, das dir am meisten bedeutet.","Stell es an einen Platz, an dem du es oft siehst.","Trag es in der App mit dem Grund „trägt Bedeutung“ ein."],
  wenn:"Wenn ich beim Aufräumen ein Stück finde, das mich sofort lächeln lässt, dann gebe ich ihm einen sichtbaren Platz, statt es zurück in die Kiste zu legen.",
  warum:"Nostalgie kann nach der Forschung Stimmung und Verbundenheit stärken, und ein sichtbares Erinnerungsstück gibt ihr vielleicht öfter einen Anlass.",
  imp:"i33" },

{ id:"u19", cat:"er", t:"Ein Geschenk, das nicht zu dir passt", d:7,
  x:"Such ein Geschenk heraus, das du nie benutzt und nur aus Pflichtgefühl behältst. Schreib eine Woche lang jeden Tag einen Satz dazu auf, was die schenkende Person dir zeigen wollte. Danach entscheidest du, ob es bleibt, weitergeht oder in die Vielleicht-Kiste kommt.",
  steps:["Such ein Geschenk heraus, das du nie benutzt.","Schreib auf, was die Person dir damit sagen wollte.","Trenn in Gedanken die Zuneigung von dem Ding.","Überleg, ob jemand das Ding wirklich gebrauchen könnte.","Entscheide in Ruhe, ob es bleibt, weitergeht oder in die Vielleicht-Kiste kommt."],
  wenn:"Wenn ich beim Gedanken ans Weitergeben ein schlechtes Gewissen bekomme, dann sage ich mir, dass die Zuneigung bleibt, egal wie ich mich entscheide.",
  warum:"In Studien sahen Schenkende das Weitergeben eines Geschenks deutlich gelassener, als die Beschenkten vermuteten.",
  imp:"i46",
  s:"Such ein eigenes Geschenk heraus, das du nie benutzt und nur aus Pflichtgefühl behältst. Schreib auf, was die Person dir damit zeigen wollte. Wenn es von jemandem aus der Familie ist, sprich mit deinen Eltern, bevor du es weitergibst." },

{ id:"u20", cat:"er", t:"Die besten Stücke einer Sammlung", d:21,
  x:"Wähl eine Sammlung aus, zum Beispiel Bücher, Karten, Steine oder Figuren. Such in drei Wochen die zehn Stücke heraus, die dir am meisten bedeuten, und stell sie gut sichtbar auf. Über die übrigen Stücke entscheidest du danach in Ruhe.",
  steps:["Wähl eine Sammlung aus, die du schon lange hast.","Leg in der ersten Woche alles einmal vor dich hin.","Such in der zweiten Woche die zehn besten Stücke heraus.","Stell sie in der dritten Woche gut sichtbar auf.","Entscheide, ob die übrigen Stücke bleiben, in die Vielleicht-Kiste kommen oder zu Menschen gehen, die sie schätzen."],
  wenn:"Wenn ich bei einem Stück außerhalb der besten zehn unsicher bin, dann frage ich mich, was ich dafür bezahlen würde, wenn es mir nicht gehören würde.",
  warum:"Was uns gehört, bewerten wir oft höher, als wir es von außen tun würden, und der Blick von außen hilft beim Auswählen.",
  imp:"i05" },

// ---------- Kaufen & Teilen ----------
{ id:"u21", cat:"ko", t:"Die 30-Tage-Wunschliste", d:30,
  x:"Kauf 30 Tage lang nichts, was nicht auf deinem Einkaufszettel stand. Jeder andere Wunsch kommt auf eine Liste mit Datum. Nach 30 Tagen schaust du, welche Wünsche noch da sind, und entscheidest dann in Ruhe.",
  steps:["Leg in der App oder auf Papier eine Wunschliste an.","Schreib jeden spontanen Kaufwunsch mit Datum darauf.","Schau dir die Liste einmal pro Woche an.","Streich Wünsche, die schon verblasst sind.","Entscheide nach 30 Tagen über jeden übrigen Wunsch."],
  wenn:"Wenn ich etwas sofort haben will, dann parke ich es als Wunsch und schaue es mir erst nach 30 Tagen wieder an.",
  warum:"Im aufgeregten Zustand schätzen wir schlecht ein, wie wir später in Ruhe darüber denken, und Warten gibt dem ruhigen Blick eine Chance.",
  imp:"i23",
  s:"Kauf 30 Tage lang nichts von deinem eigenen Geld, was du nicht schon vorher geplant hattest. Jeder andere Wunsch kommt mit Datum auf eine Liste. Nach 30 Tagen schaust du, was du noch willst, und entscheidest dann." },

{ id:"u22", cat:"ko", t:"Leihen statt kaufen", d:14,
  x:"Wenn du in den nächsten zwei Wochen etwas brauchst, das du selten benutzt, leihst du es. Frag Nachbarn, Freunde, eine Leihbücherei oder einen Leihladen. Achte darauf, wie das Leihen klappt und was es dich kostet.",
  steps:["Schreib auf, was du in nächster Zeit brauchen könntest.","Such heraus, wo man in deiner Nähe Dinge leihen kann.","Frag mindestens einmal jemanden direkt, ob er dir etwas leiht.","Gib das Geliehene sauber und pünktlich zurück.","Biete selbst etwas zum Leihen an."],
  wenn:"Wenn ich etwas kaufen will, das ich voraussichtlich nur ein paar Mal im Jahr brauche, dann frage ich zuerst in meiner Nachbarschaft, ob es jemand verleiht.",
  warum:"Die bekannte Zahl zur kaum benutzten Bohrmaschine ist schlecht belegt, darum findest du durch eigenes Ausprobieren heraus, ob Leihen für dich passt.",
  imp:"i30",
  s:"Wenn du in den nächsten zwei Wochen etwas brauchst, das du selten benutzt, leihst du es. Frag Freunde, Geschwister, die Stadtbücherei oder die Schule. Gib alles sauber und pünktlich zurück." },

{ id:"u23", cat:"ko", t:"Die Einkaufszettel-Regel", d:14,
  x:"Geh zwei Wochen lang nur mit einem Einkaufszettel einkaufen, im Laden und im Netz. Du kaufst nur, was darauf steht. Alles andere, was dir unterwegs gefällt, schreibst du auf und parkst es als Wunsch.",
  steps:["Schreib vor jedem Einkauf einen Zettel.","Nimm im Laden nur, was auf dem Zettel steht.","Notiere andere Dinge, die dir gefallen, auf der Rückseite.","Übertrag diese Dinge zu Hause in deine Wunschliste."],
  wenn:"Wenn ich im Laden etwas in die Hand nehme, das nicht auf dem Zettel steht, dann lege ich es zurück und schreibe es auf die Rückseite.",
  warum:"Viele Studien zeigen, dass ein vorher festgelegter Wenn-dann-Plan hilft, Vorsätze in Situationen umzusetzen, in denen man sonst aus Gewohnheit handelt.",
  imp:"i24",
  s:"Geh zwei Wochen lang nur mit einem Zettel einkaufen, wenn du dein eigenes Geld ausgibst, auch im Netz. Du kaufst nur, was darauf steht. Alles andere, was dir gefällt, parkst du als Wunsch." },

{ id:"u24", cat:"ko", t:"Vorfreude auf ein Erlebnis", d:14,
  x:"Statt dir in den nächsten zwei Wochen etwas zu kaufen, planst du ein kleines Erlebnis. Das kann ein Ausflug, ein Abend mit Freunden oder ein Kurs sein. Es muss wenig oder nichts kosten. Achte auf die Vorfreude bis zum Termin.",
  steps:["Such dir ein Erlebnis aus, auf das du Lust hast.","Leg einen Termin in den nächsten zwei Wochen fest.","Lad mindestens einen Menschen ein.","Schreib zwischendurch auf, worauf du dich freust.","Notiere danach, woran du dich gern erinnerst."],
  wenn:"Wenn ich merke, dass ich mir aus Langeweile etwas kaufen will, dann plane ich stattdessen den nächsten Schritt für mein Erlebnis.",
  warum:"In Studien fühlte sich die Vorfreude auf ein Erlebnis angenehmer an als die Vorfreude auf ein neues Ding.",
  imp:"i02",
  s:"Statt dir in den nächsten zwei Wochen etwas zu kaufen, planst du ein kleines Erlebnis, das wenig oder nichts kostet. Das kann ein Ausflug mit dem Rad, ein Filmabend oder ein Picknick sein. Sprich den Termin mit deinen Eltern ab." },

{ id:"u25", cat:"ko", t:"Die Pause beim Frustkauf", d:7,
  x:"Achte eine Woche lang darauf, wann du aus schlechter Laune etwas kaufen willst. In diesem Moment machst du zehn Minuten lang etwas anderes, das dir guttut. Danach entscheidest du, ob du den Wunsch noch willst oder parkst.",
  steps:["Schreib drei Dinge auf, die dir bei schlechter Laune guttun und nichts kosten.","Merk dir, wann du aus Ärger oder Langeweile in einen Shop schaust.","Mach in diesem Moment zehn Minuten etwas von deiner Liste.","Park den Wunsch danach, wenn er noch da ist."],
  wenn:"Wenn ich nach einem schlechten Tag einen Shop öffne, dann gehe ich zuerst zehn Minuten nach draußen oder rufe jemanden an.",
  warum:"Nach einer Studie lindert schon das Auswählen Traurigkeit kurz, weil es ein Gefühl von Kontrolle gibt, und die Übung sucht Wege, die das ohne Kauf schaffen.",
  imp:"i20",
  s:"Achte eine Woche lang darauf, wann du aus schlechter Laune etwas kaufen oder dir wünschen willst. In diesem Moment machst du zehn Minuten etwas anderes, das dir guttut. Danach entscheidest du, ob du den Wunsch parkst." },

{ id:"u26", cat:"ko", t:"Werbung bei Influencern erkennen", d:7,
  x:"Achte eine Woche lang bei Videos und Posts von Menschen, denen du folgst, darauf, wo Werbung steckt. Hinweise sind Wörter wie „Werbung“ oder „Anzeige“, Rabattcodes und Links zu Shops. Am Ende entscheidest du, wem du weiter folgen möchtest.",
  steps:["Nimm dir vor, eine Woche lang bei jedem Post kurz auf Werbung zu achten.","Notiere, wenn du „Werbung“, „Anzeige“, einen Rabattcode oder einen Shop-Link siehst.","Schreib dazu, ob du danach etwas haben wolltest.","Schau am Ende, bei welchen Kanälen das am häufigsten vorkam.","Entscheide, ob du einem Kanal entfolgst, ihn stummschaltest oder weiter schaust."],
  wenn:"Wenn ich in einem Video einen Rabattcode höre, dann parke ich den Wunsch, statt den Link zu öffnen.",
  warum:"Bei Kindern ging mehr Werbung mit stärkeren Wünschen nach den beworbenen Dingen einher, und wer Werbung erkennt, kann leichter Abstand nehmen.",
  imp:"i36",
  s:"Achte eine Woche lang bei Videos und Posts, die du dir anschaust, darauf, wo Werbung steckt. Hinweise sind Wörter wie „Werbung“ oder „Anzeige“, Rabattcodes und Links zu Shops. Am Ende entscheidest du selbst, wem du weiter folgen möchtest." },

{ id:"u27", cat:"ko", t:"In-Game-Käufe eine Woche beobachten", d:7,
  x:"Beobachte eine Woche lang, wann dir ein Spiel etwas zum Kaufen anbietet, etwa Skins, Lootboxen oder Spielwährung. Kauf in dieser Woche nichts davon und notiere nur, was dich gereizt hätte. Danach legst du eine eigene Grenze für den nächsten Monat fest.",
  steps:["Schau nach, wie viel du im letzten Monat in Spielen ausgegeben hast, falls du das sehen kannst.","Notiere eine Woche lang jedes Angebot, das dich gereizt hat, und wann es kam.","Kauf in dieser Woche nichts im Spiel.","Schau am Ende, welche Angebote nach ein paar Tagen noch wichtig waren.","Leg eine feste Grenze für den nächsten Monat fest, zum Beispiel einen Betrag oder eine Zahl von Käufen."],
  wenn:"Wenn ein Spiel mir ein zeitlich begrenztes Angebot zeigt, dann schließe ich es und schreibe den Wunsch auf.",
  warum:"Ein Plan, der eine konkrete Situation nennt, hilft nach vielen Studien, Vorsätze auch im Moment des Reizes umzusetzen.",
  imp:"i24",
  s:"Beobachte eine Woche lang, wann dir ein Spiel etwas zum Kaufen anbietet, etwa Skins, Lootboxen oder Spielwährung. Kauf in dieser Woche nichts davon und notiere, was dich gereizt hätte. Danach legst du eine Grenze fest, zusammen mit deinen Eltern, wenn deren Konto oder Karte im Spiel hinterlegt ist." },

{ id:"u28", cat:"ko", t:"„Jetzt kaufen, später zahlen“ verstehen", d:3,
  x:"Viele Shops bieten an, jetzt zu kaufen und erst später oder in Raten zu zahlen. Schau dir drei Tage lang an, wie das funktioniert, ohne etwas zu bestellen. Lies bei einem Angebot nach, wann gezahlt werden muss und was passiert, wenn eine Zahlung zu spät kommt.",
  steps:["Such bei einem Shop, den du kennst, die Bezahlart „später zahlen“ oder „in Raten“.","Lies nach, bis wann gezahlt werden muss und wer das Geld eigentlich verleiht.","Such heraus, was bei verspäteter Zahlung passiert, etwa Mahngebühren oder Zinsen.","Überleg, wie viele solche Zahlungen man gleichzeitig im Blick behalten könnte.","Notiere in einem Satz, wann du diese Bezahlart für sinnvoll hältst und wann nicht."],
  wenn:"Wenn mir ein Shop „später zahlen“ anbietet, dann frage ich mich, ob ich den Betrag heute schon hätte.",
  warum:"Im aufgeregten Moment unterschätzen wir leicht, wie wir später über eine Ausgabe denken, und wer erst später zahlt, spürt die Kosten vielleicht erst dann.",
  imp:"i23",
  s:"Viele Shops bieten an, jetzt zu kaufen und später oder in Raten zu zahlen. Schau dir drei Tage lang an, wie das funktioniert, ohne etwas zu bestellen. Lies nach, wann gezahlt werden muss und was passiert, wenn eine Zahlung zu spät kommt." },

// ---------- Methoden aus der Aufräumszene (Erfahrungsregeln, nicht untersucht) ----------
{ id:"u29", cat:"wo", t:"Ein Fach ist die Grenze", d:7,
  x:"Wähl eine Sorte Dinge, etwa Schals, Stifte oder Tassen, und ein festes Fach dafür. Zuerst kommen deine Lieblingsstücke hinein, bis das Fach voll ist. Was nicht passt, kommt in die Vielleicht-Kiste. Die Idee stammt von der Autorin Dana K. White. Das ist eine bewährte Regel aus der Aufräumszene, untersucht ist sie nicht.",
  steps:["Such dir eine Sorte Dinge aus, von der du viel hast.","Leg ein Fach, eine Schublade oder eine Kiste als Grenze fest.","Räum zuerst deine Lieblingsstücke hinein.","Füll das Fach mit den nächstliebsten Stücken, bis es voll ist.","Leg den Rest in die Vielleicht-Kiste und schau nach 30 Tagen, was dir gefehlt hat."],
  wenn:"Wenn das Fach voll ist und ich mir etwas Neues dieser Sorte wünsche, dann parke ich den Wunsch zuerst.",
  warum:"Ein begrenztes Fach lässt dich zwischen guten Stücken wählen, statt über jedes einzelne zu grübeln, und Zögern beim Entscheiden hängt in Befragungen mit mehr Last durch Unordnung zusammen.",
  imp:"i53",
  s:"Wähl eine Sorte eigener Dinge, etwa Stifte, Haargummis oder Kuscheltiere, und ein festes Fach in deinem Zimmer. Zuerst kommen deine Lieblingsstücke hinein. Was nicht passt, kommt in die Vielleicht-Kiste. Das ist eine bewährte Regel aus der Aufräumszene, untersucht ist sie nicht." },

{ id:"u30", cat:"ko", t:"Erst aufbrauchen", d:21,
  x:"Wähl eine Sorte Verbrauchsdinge, von der du mehrere offen hast, etwa Duschgel, Creme, Stifte oder Notizhefte. Drei Wochen lang kaufst du davon nichts Neues und brauchst zuerst auf, was da ist. Weggeworfen wird dabei nichts. Das ist eine bewährte Regel aus der Aufräumszene, untersucht ist sie nicht.",
  steps:["Such eine Sorte aus, von der mehrere Packungen angebrochen sind.","Stell alles an einen Platz, an dem du es siehst.","Nimm immer zuerst die älteste oder fast leere Packung.","Park Nachkauf-Wünsche als Wunsch, statt gleich zu kaufen.","Schau nach drei Wochen, was leer geworden ist und was dir gefehlt hat."],
  wenn:"Wenn ich Lust auf ein neues Duschgel oder einen neuen Stift habe, dann schaue ich zuerst, ob noch eines offen ist.",
  warum:"Vorsichtig einkaufen und Dinge lange nutzen gehören in einer großen Befragung zu den vier Seiten von Minimalismus, und weil beim Aufbrauchen nichts Neues gekauft und nichts weggeworfen wird, ist es zugleich Suffizienz im Kleinen.",
  imp:"i51",
  s:"Wähl eine Sorte eigener Verbrauchsdinge, von der du mehrere offen hast, etwa Stifte, Hefte, Duschgel oder Haarspray. Drei Wochen lang kaufst du davon nichts Neues und brauchst zuerst auf, was da ist. Das ist eine bewährte Regel aus der Aufräumszene, untersucht ist sie nicht." },

{ id:"u31", cat:"wo", t:"Zehn Minuten mit Zeitgeber", d:7,
  x:"Stell eine Woche lang jeden Tag einen Zeitgeber auf zehn Minuten und räum in dieser Zeit eine kleine Fläche auf. Wenn der Zeitgeber klingelt, hörst du auf. Kurze Einheiten sind eine bewährte Regel aus der Aufräumszene, untersucht sind sie nicht. Sie sollen das Anfangen leichter machen.",
  steps:["Such dir für jeden Tag eine kleine Fläche aus, etwa einen Stuhl, ein Regalbrett oder den Eingang.","Stell den Zeitgeber auf zehn Minuten.","Fang mit dem an, was du am deutlichsten siehst.","Hör auf, wenn der Zeitgeber klingelt.","Notiere kurz, was du geschafft hast."],
  wenn:"Wenn ich merke, dass ich das Aufräumen schon wieder verschiebe, dann stelle ich den Zeitgeber auf zehn Minuten und fange sofort an.",
  warum:"Unordnung hängt in Befragungen mit Aufschieben zusammen, und ein kurzer, fester Zeitrahmen kann das Anfangen leichter machen; ob das bei dir so ist, zeigt nur dein eigener Versuch.",
  imp:"i53",
  s:"Stell eine Woche lang jeden Tag einen Zeitgeber auf zehn Minuten und räum in dieser Zeit eine kleine Fläche in deinem Zimmer auf, etwa den Stuhl oder den Schreibtisch. Wenn der Zeitgeber klingelt, hörst du auf. Kurze Einheiten sind eine bewährte Regel aus der Aufräumszene, untersucht sind sie nicht." },

{ id:"u32", cat:"wo", t:"Die 90-Tage-Frage", d:7,
  x:"Nimm eine Woche lang jeden Tag fünf Dinge aus einem Bereich in die Hand. Frag bei jedem: Habe ich es in den letzten 90 Tagen benutzt? Werde ich es in den nächsten 90 Tagen benutzen? Die Regel stammt vom Blog „The Minimalists“. Sie ist eine Erfahrungsregel, untersucht ist sie nicht.",
  steps:["Wähl einen Bereich aus, etwa Küche, Bad oder Schreibtisch.","Nimm jeden Tag fünf Dinge in die Hand.","Stell bei jedem die beiden 90-Tage-Fragen.","Passt der Zeitraum nicht, etwa bei Winterjacken oder Werkzeug, nimm ein ganzes Jahr.","Leg Dinge mit zweimal Nein in die Vielleicht-Kiste, statt sie sofort wegzugeben."],
  wenn:"Wenn ich bei einem Ding zweimal Nein sage, dann lege ich es in die Vielleicht-Kiste und entscheide nach 30 Tagen.",
  warum:"Die Fragen ersetzen grobes Schätzen durch einen klaren Zeitraum, und ob dein Gefühl stimmt, prüft danach die Vielleicht-Kiste.",
  imp:"i48",
  s:"Nimm eine Woche lang jeden Tag fünf eigene Dinge in die Hand, etwa vom Schreibtisch oder aus dem Regal. Frag bei jedem: Habe ich es in den letzten 90 Tagen benutzt? Werde ich es in den nächsten 90 Tagen benutzen? Das ist eine Erfahrungsregel, untersucht ist sie nicht." },

{ id:"u33", cat:"wo", t:"Zwei Fragen für Dinge ohne Platz", d:5,
  x:"Nimm dir fünf Tage lang herumliegende Dinge ohne festen Platz vor. Frag bei jedem: Wo würde ich zuerst danach suchen? Dorthin bringst du es sofort. Gibt es keine Antwort, fragst du: Würde mir einfallen, dass ich so etwas habe? Die Fragen stammen von der Autorin Dana K. White und sind nicht untersucht.",
  steps:["Nimm dir jeden Tag fünf herumliegende Dinge vor.","Frag: Wo würde ich zuerst danach suchen?","Bring das Ding sofort an genau diesen Ort.","Hast du keine Antwort, frag: Würde mir überhaupt einfallen, dass ich so etwas habe?","Ist die Antwort Nein, leg es in die Weitergeben-Tüte oder in die Vielleicht-Kiste."],
  wenn:"Wenn ich ein Ding in der Hand habe und nicht weiß, wohin damit, dann frage ich mich, wo ich zuerst danach suchen würde.",
  warum:"Wer beim Entscheiden zögert, leidet in Befragungen stärker unter Unordnung, und zwei feste Fragen machen die Entscheidung kürzer.",
  imp:"i53",
  s:"Nimm dir fünf Tage lang eigene Dinge ohne festen Platz vor. Frag bei jedem: Wo würde ich zuerst danach suchen? Dorthin bringst du es. Dinge, die anderen gehören, bringst du zu ihnen zurück. Die Fragen stammen von der Autorin Dana K. White und sind nicht untersucht." },

{ id:"u34", cat:"er", t:"Freundlich vorsorgen", d:14,
  x:"Das schwedische Wort „Döstädning“ meint, rechtzeitig und in Ruhe auszusortieren. Die Frage dahinter ist freundlich: Was soll später niemand für dich sortieren müssen? Zwei Wochen lang gehst du einen Bereich so durch, erst Großes, zuletzt Fotos und Briefe. Das ist eine Erfahrungsregel, untersucht ist sie nicht.",
  steps:["Wähl einen Bereich, etwa Keller, Abstellraum oder einen Schrank.","Fang mit großen, unpersönlichen Dingen an.","Frag bei jedem: Würde sich jemand darüber freuen, oder müsste er es später nur sortieren?","Frag Angehörige, ob sie sich ein bestimmtes Stück wünschen.","Nimm Fotos, Briefe und Erinnerungsstücke zuletzt in die Hand und lass dir dafür Zeit."],
  wenn:"Wenn ich bei einem Ding zögere, dann frage ich mich, ob es jemandem später Freude macht oder nur Arbeit.",
  warum:"Die Frage richtet den Blick auf Menschen statt auf Dinge, und Erinnerungen an Menschen tun nach der Nostalgieforschung oft gut, auch wenn nicht jedes Ding bleiben muss.",
  imp:"i33",
  s:"Stell dir vor, du ziehst bald um und nimmst nur mit, was dir wichtig ist. Zwei Wochen lang gehst du deine eigenen Sachen mit der Frage durch: Würde ich das einpacken? Fang mit Großem an, Fotos und Briefe kommen zuletzt. Das ist eine Erfahrungsregel, untersucht ist sie nicht." },

{ id:"u35", cat:"ko", t:"Abraten-Videos prüfen", d:7,
  x:"Schau dir eine Woche lang bewusst Videos an, in denen jemand vom Kaufen abrät. Achte darauf, ob am Ende doch ein anderes Produkt, ein Link oder ein Rabattcode kommt. Danach weißt du, welche Kanäle nur abraten und welche auf andere Weise werben.",
  steps:["Such dir drei Videos, in denen jemand von einem Produkt abrät.","Notiere, ob statt des Produkts ein anderes empfohlen wird.","Achte auf Links, Rabattcodes und die Hinweise „Werbung“ oder „Anzeige“.","Schreib auf, ob du danach etwas haben wolltest.","Entscheide, welchen Kanälen du weiter folgen möchtest."],
  wenn:"Wenn ein Abraten-Video mir am Ende eine Alternative empfiehlt, dann parke ich den Wunsch, statt den Link zu öffnen.",
  warum:"In einem kleinen Versuch beeinflussten auch Abraten-Videos die Kaufabsicht, oft weil sie gleich eine Alternative empfahlen.",
  imp:"i57" }
];

const BEGRIFFE=[
{ id:"b01", t:"Besitztumseffekt",
  x:"Sobald uns etwas gehört, bewerten wir es höher als vorher. Wir verlangen für ein Ding oft mehr Geld, als wir selbst dafür bezahlen würden. Das erklärt zum Teil, warum Weggeben schwerer fällt als Nichtkaufen.",
  bsp:"Lena will ihre alte Kamera für 120 Euro verkaufen. Wenn sie dieselbe Kamera bei jemand anderem sehen würde, würde sie höchstens 60 Euro dafür bezahlen.",
  imp:"i05" },
{ id:"b02", t:"Versunkene Kosten",
  x:"Geld, Zeit oder Mühe, die schon ausgegeben sind und nicht zurückkommen. Trotzdem lassen wir uns oft davon leiten und halten an etwas fest, nur weil wir schon viel hineingesteckt haben.",
  bsp:"Tom hat 80 Euro für ein Konzert bezahlt. Am Abend ist er erkältet und hat keine Lust, geht aber trotzdem hin, weil das Ticket ja schon bezahlt ist.",
  imp:"i06" },
{ id:"b03", t:"Hedonische Anpassung",
  x:"Wir gewöhnen uns schnell an Neues. Die Freude über ein neues Ding wird mit der Zeit schwächer, bis es sich normal anfühlt. Dann entsteht leicht der Wunsch nach dem nächsten neuen Ding.",
  bsp:"Mia hat sich monatelang auf ihr neues Handy gefreut. Drei Wochen später nimmt sie es in die Hand wie das alte und denkt kaum noch darüber nach.",
  imp:"i04" },
{ id:"b04", t:"Erlebniskauf",
  x:"Geld, das man für etwas ausgibt, das man tut statt besitzt, zum Beispiel eine Reise, ein Konzert oder einen Kurs. Solche Ausgaben machen nach vielen Studien im Durchschnitt etwas länger zufrieden als Dinge, der Vorteil ist aber klein.",
  bsp:"Jan gibt sein Erspartes nicht für eine neue Jacke aus, sondern für ein Wochenende Zelten mit seiner Schwester. Noch Jahre später erzählen beide davon.",
  imp:"i01" },
{ id:"b05", t:"Überhälter",
  x:"Ein Wort aus der Forstsprache. Es meint einen Baum, den Förster beim Fällen oder Lichten eines Waldstücks bewusst stehen lassen. Übertragen passt es auf die wenigen Dinge, die du mit gutem Grund behältst.",
  bsp:"Im Wald wird eine Fläche gefällt. Eine alte, gesunde Eiche lassen die Förster mit Absicht allein stehen, damit sie Samen für den neuen Wald liefert." },
{ id:"b06", t:"Moralische Lizenz",
  x:"Nach einer guten Tat erlauben wir uns manchmal, danach weniger gut zu handeln. Die gute Tat fühlt sich an wie ein Guthaben. Wie stark dieser Effekt ist, ist nach neueren Wiederholungen umstritten.",
  bsp:"Paul bringt morgens drei Tüten Kleidung zur Kleiderkammer. Am Nachmittag kauft er sich zwei neue Hemden, weil er findet, dass er heute schon genug Gutes getan hat.",
  imp:"i41" },
{ id:"b07", t:"Wenn-dann-Plan",
  x:"Ein Vorsatz, der eine bestimmte Situation mit einer bestimmten Handlung verbindet. Man legt vorher fest, was man in diesem Moment tut. So muss man im schwierigen Moment nicht neu entscheiden, und das geplante Verhalten fällt leichter.",
  bsp:"Sara legt fest: Sobald sie im Laden etwas Ungeplantes in der Hand hält, legt sie es zurück und schreibt es auf ihre Liste.",
  imp:"i24" },
{ id:"b08", t:"Neustart-Effekt",
  x:"Zu Beginn eines neuen Abschnitts nehmen wir uns eher etwas vor, zum Beispiel am Jahresanfang, an einem Montag oder nach dem Geburtstag. Der alte Abschnitt fühlt sich abgeschlossen an, und das macht Mut für Veränderung.",
  bsp:"Am ersten Tag nach den Sommerferien beschließt Ali, endlich seine Schreibtischschubladen auszuräumen. Den Plan hatte er schon seit Monaten, aber jetzt fühlt es sich wie ein guter Anfang an.",
  imp:"i25" },
{ id:"b09", t:"Empathielücke heiß-kalt",
  x:"In einem ruhigen Zustand unterschätzen wir, wie stark uns Gefühle wie Aufregung, Hunger oder Lust später lenken. In einem aufgeregten Zustand können wir uns umgekehrt kaum vorstellen, wie wir in Ruhe darüber denken würden.",
  bsp:"Am entspannten Sonntag findet Ben, dass er keine neuen Kopfhörer braucht. Am Montag sieht er ein Angebot, ist ganz aufgeregt und kann sich kaum noch vorstellen, wie gelassen er gestern war.",
  imp:"i23" },
{ id:"b10", t:"Statusgut",
  x:"Ein Ding, das vor allem deshalb begehrt ist, weil es zeigt, wo man im Vergleich mit anderen steht. Sein Wert hängt weniger davon ab, was es kann, als davon, was andere besitzen.",
  bsp:"Elias wünscht sich eine bestimmte Uhr, damit seine Clique sieht, dass er mithalten kann. Eine gleich gute Uhr ohne bekannten Namen will er nicht.",
  imp:"i37" },
{ id:"b11", t:"IKEA-Effekt",
  x:"Dinge, die wir selbst gebaut oder zusammengesetzt haben, schätzen wir mehr als gleiche Dinge, die fertig gekauft wurden. Die eigene Mühe macht sie für uns wertvoller, auch wenn das Ergebnis nicht perfekt ist.",
  bsp:"Jonas hat sein Regal selbst zusammengeschraubt, und es steht etwas schief. Trotzdem findet er es schöner als das gleiche Regal, das sein Mitbewohner fertig aufgebaut geliefert bekam.",
  imp:"i39" },
{ id:"b12", t:"Wahlüberlastung",
  x:"Die Annahme, dass zu viele Möglichkeiten Entscheidungen erschweren, bis man unzufrieden ist oder gar nicht entscheidet. Metaanalysen zeigen, dass das nicht immer gilt, sondern von der Situation abhängt.",
  bsp:"Lea steht im Supermarkt vor 40 Sorten Müsli. Nach zehn Minuten Vergleichen geht sie ohne Müsli nach Hause.",
  imp:"i32" },
{ id:"b13", t:"Kapselgarderobe",
  x:"Eine kleine, bewusst zusammengestellte Sammlung von Kleidung, deren Teile gut zueinanderpassen. Man kann fast alles miteinander kombinieren und kommt mit wenigen Stücken durch eine Jahreszeit.",
  bsp:"Malte hat für Herbst und Winter 15 Kleidungsstücke, die alle in ähnlichen Farben sind und zueinander passen. Morgens zieht er etwas daraus an, ohne lange zu überlegen.",
  imp:"i42" },
{ id:"b14", t:"Rebound-Effekt",
  x:"Wenn etwas sparsamer oder billiger wird, nutzen Menschen es oft mehr. Dadurch wird ein Teil der Ersparnis wieder aufgezehrt. Manchmal verbraucht man am Ende sogar mehr als vorher.",
  bsp:"Familie Kaya kauft ein Auto, das wenig Benzin verbraucht. Weil das Fahren jetzt günstiger ist, fahren sie viel öfter, und am Ende tanken sie kaum weniger als vorher.",
  imp:"i43" },
{ id:"b15", t:"Suffizienz",
  x:"Suffizienz fragt nach dem richtigen Maß: Wie viel brauche ich eigentlich? Effizienz macht Dinge sparsamer, Konsistenz macht sie umweltverträglicher. Suffizienz senkt den Verbrauch dagegen, indem man insgesamt weniger braucht und nutzt.",
  bsp:"Familie Roth braucht einen neuen Kühlschrank. Sie vergleicht nicht zuerst den Stromverbrauch großer Modelle, sondern merkt, dass ein kleiner Kühlschrank für ihren Alltag völlig reicht.",
  imp:"i58" },
{ id:"b16", t:"Kreislaufwirtschaft",
  x:"Eine Wirtschaft, in der Dinge möglichst lange genutzt, geteilt, repariert und weitergegeben werden. Erst ganz am Ende werden ihre Stoffe recycelt. So entsteht weniger Abfall, und es werden weniger neue Rohstoffe gebraucht.",
  bsp:"Ein Sportgeschäft nimmt zu klein gewordene Kinderskier zurück, lässt sie prüfen und verleiht sie im nächsten Winter an andere Familien. Kaputte Skier zerlegt es, damit die Materialien neu verwendet werden können." },
{ id:"b17", t:"Freiwillige Einfachheit",
  x:"Eine Lebensweise, bei der Menschen aus eigenem Entschluss weniger kaufen und besitzen, als sie könnten. Sie tun das, um mehr Zeit, Ruhe oder Sinn zu gewinnen. Es geht um eine freie Wahl, nicht um Not.",
  bsp:"Dana könnte mit einer vollen Stelle mehr verdienen. Sie arbeitet aus eigenem Entschluss nur vier Tage, kauft wenig und hat dafür Zeit für Garten, Freunde und Ehrenamt.",
  imp:"i14" },
{ id:"b18", t:"Materialismus (psychologisch)",
  x:"In der Psychologie meint das Wort nicht einfach Besitz, sondern eine Haltung. Wer materialistisch denkt, hält Reichtum und Besitz für sehr wichtig, um glücklich zu sein und vor anderen gut dazustehen.",
  bsp:"Für Jana ist ein Leben dann gelungen, wenn man viel Geld und schöne Dinge hat. Sie glaubt, dass sie glücklicher wäre, wenn sie mehr besäße.",
  imp:"i12" },
{ id:"b19", t:"Deinfluencing",
  x:"Ein Trend in sozialen Medien, bei dem Creator davon abraten, bestimmte Dinge zu kaufen. Das kann zu überlegterem Kaufen anregen. Oft wird aber gleich ein anderes Produkt empfohlen, und dann ist es selbst wieder eine Form von Werbung.",
  bsp:"Eine Creatorin sagt in einem Video, eine teure Wimperntusche lohne sich nicht. Am Ende hält sie eine günstigere Marke in die Kamera und nennt einen Rabattcode.",
  imp:"i57" },
{ id:"b20", t:"Aufschieben (Prokrastination)",
  x:"Man verschiebt eine Aufgabe immer wieder, obwohl man weiß, dass sie wichtig ist und das Warten Nachteile hat. In Befragungen hängt häufiges Aufschieben mit mehr Problemen durch Unordnung zu Hause zusammen.",
  bsp:"Seit Wochen will Kim den Stapel Zettel auf ihrem Schreibtisch sortieren. Jeden Abend sagt sie sich, dass morgen ein besserer Tag dafür ist.",
  imp:"i53" },
{ id:"b21", t:"Unauffälliger Konsum",
  x:"Teure Dinge, die ihren Wert nicht laut zeigen: kein großes Logo, schlichtes Aussehen, hohe Qualität. Wer sich auskennt, erkennt den Preis trotzdem. So kann auch Schlichtes zeigen, wo jemand im Vergleich mit anderen steht.",
  bsp:"Felix trägt einen einfachen grauen Pullover ohne Aufdruck. Nur wer die Marke kennt, weiß, dass er so viel gekostet hat wie fünf andere Pullover.",
  imp:"i47" },
{ id:"b22", t:"Döstädning",
  x:"Ein schwedisches Wort, etwa „Aufräumen vor dem Tod“. Gemeint ist, rechtzeitig und in Ruhe auszusortieren, damit Angehörige später nicht alles allein sortieren müssen. Bekannt wurde es durch ein Buch von Margareta Magnusson.",
  bsp:"Frau Berg ist 72. Sie geht in Ruhe ihren Keller durch, schenkt ihrer Enkelin das Nähkästchen und schreibt zu den Fotoalben, wer darauf zu sehen ist." }
];

const MONATE=[
{ t:"Neustart und Papier", x:"Der Jahresanfang fühlt sich für viele wie ein neuer Abschnitt an, und das macht Vorsätze leichter. Ein guter Start ist der Papierstapel, der sich über das alte Jahr angesammelt hat.", cat:"pa", u:"u11" },
{ t:"Lange Abende für Erinnerungen", x:"Im Februar sind die Abende noch lang und dunkel. Das ist eine ruhige Zeit, um eine Kiste mit Erinnerungsstücken zu öffnen und ihre Geschichten aufzuschreiben.", cat:"er", u:"u16" },
{ t:"Kleidung beim Saisonwechsel", x:"Wenn die Wintersachen nach hinten wandern, ist ein guter Moment für einen Blick in den Schrank. Mit umgedrehten Bügeln siehst du nach 30 Tagen, was du wirklich trägst.", cat:"kl", u:"u02" },
{ t:"Frühjahrsputz in kleinen Schritten", x:"Im Frühling haben viele Lust, aufzuräumen. Eine Schublade am Tag kann diese Lust wachhalten, ohne dass ein ganzes Wochenende dafür draufgeht.", cat:"wo", u:"u06" },
{ t:"Leihen für Garten und Balkon", x:"Im Mai braucht man für Garten, Balkon und Fahrrad oft Geräte, die man nur selten benutzt. Das ist eine gute Gelegenheit, das Leihen auszuprobieren.", cat:"ko", u:"u22" },
{ t:"Urlaub als Erlebnis", x:"Vor dem Sommer planen viele ihren Urlaub. Die Vorfreude auf ein Erlebnis kann schon ein Teil davon sein. Es muss keine weite Reise sein, und nahe Ziele schonen das Klima.", cat:"ko", u:"u24" },
{ t:"Ferien mit offenen Augen", x:"In den Sommerferien entstehen viele Fotos. Wer zuerst schaut und dann fotografiert, hat am Ende weniger Bilder und vielleicht bessere Erinnerungen.", cat:"pa", u:"u14" },
{ t:"Schulanfang mit Einkaufszettel", x:"Vor dem Schulbeginn und nach dem Urlaub wird viel eingekauft. Ein Zettel hilft, nur zu kaufen, was wirklich fehlt.", cat:"ko", u:"u23" },
{ t:"Kleidung für den Herbst", x:"Wenn die warmen Sachen wieder nach vorn kommen, lohnt sich ein Test. Eine Woche mit der halben Kleiderstange zeigt, wie viel du für den Herbst brauchst.", cat:"kl", u:"u01" },
{ t:"Werkzeug und Reparieren", x:"Im Herbst ist man mehr drinnen und hat Zeit für Dinge, die lange liegen geblieben sind. Das kaputte Gerät aus dem Schrank ist ein guter Anfang.", cat:"wo", u:"u07" },
{ t:"Rabattwochen gelassen nehmen", x:"Im November locken viele Shops mit großen Rabatten. Eine Wunschliste mit 30 Tagen Wartezeit trennt echte Wünsche von der Aufregung des Angebots.", cat:"ko", u:"u21" },
{ t:"Geschenke und Erlebnisse", x:"Im Dezember wird viel geschenkt. Ein gemeinsames Erlebnis als Geschenk braucht keinen Platz im Regal und kann zwei Menschen verbinden.", cat:"er", u:"u17" }
];

